function verifier(string $nom): void
{
    $messages = [
        "1019701b85471d96fcf7389a31ecd436f30031a9b9b19baf8a55c72e0786d625" => "Bien joué, vous tenez le saboteur ! Mais il n'a pas agi seul : lisez son témoignage pour découvrir qui l'a payé, puis appelez à nouveau verifier() avec le nouveau nom.",
        "4fb621eb4be266658adba73e8f3f14fa8690fa5475cced44bc668c4f2511da0a" => "Félicitations ! La présidente du club rival voulait récupérer l'organisation du tournoi. Grâce à vous, il aura bien lieu au Gymnase municipal d'Algoville.",
    ];
    $empreinte = hash('sha256', strtolower(trim($nom)));
    echo "\n[[ENQUETE:" . (isset($messages[$empreinte]) ? $empreinte : "KO") . "]]\n";
    if (isset($messages[$empreinte])) {
        echo $messages[$empreinte] . "\n";
    } else {
        echo "Ce n'est pas la bonne personne. Essayez encore !\n";
    }
}

